INSERT INTO theme (name, icon_url, sort_order, is_locked, subject_id) VALUES ('绘本小火车', '/images/picturebooks/train-station.jpg', 0, 0, 1);
INSERT INTO unit (theme_id, name, sort_order, is_locked) SELECT id, '溪边秋千 · 绘本1', 1, 0 FROM theme WHERE name = '绘本小火车';
INSERT INTO lesson (unit_id, name, type, content, sort_order, star_reward) SELECT unit.id, '故事站 · 溪边探险', 'READING', '{"type": "READING", "picturebook": true, "bookTitle": "溪边秋千 · 绘本1", "items": [{"title": "检票上车", "content": "Tickets, please!", "translation": "请出示车票！点一下车票，成为今天的小司机。", "image": "picturebooks/train-station", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "ticket", "announcement": "欢迎乘坐绘本小火车！先检票，再出发。"}, {"title": "听指令发车", "content": "Go!", "translation": "出发！听到 Go，就按“发车”。", "image": "picturebooks/train-station", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "signal", "announcement": "这是英语指令小游戏。Go 表示出发，Stop 表示停下。"}, {"title": "故事第 1 页", "content": "The children went to the stream.", "translation": "孩子们去了小溪边。", "image": "picturebooks/stream-swing/page-01", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "", "announcement": "故事列车到达第 1 站。看看窗外发生了什么。"}, {"title": "故事第 2 页", "content": "They looked at the swing. Wilf climbed on the swing.", "translation": "他们看着秋千。Wilf 爬上了秋千。", "image": "picturebooks/stream-swing/page-02", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "观察站到了！秋千是用什么做的？说给站长听听。", "announcement": "故事列车到达第 2 站。看看窗外发生了什么。"}, {"title": "故事第 3 页", "content": "Chip pushed Wilf.", "translation": "Chip 推了 Wilf。", "image": "picturebooks/stream-swing/page-03", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "", "announcement": "故事列车到达第 3 站。看看窗外发生了什么。"}, {"title": "故事第 4 页", "content": "Floppy looked at the rope.", "translation": "Floppy 看着绳子。", "image": "picturebooks/stream-swing/page-04", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "小侦探站：Floppy 在看哪里？你发现绳子了吗？", "announcement": "故事列车到达第 4 站。注意观察 Floppy。"}, {"title": "故事第 5 页", "content": "Biff climbed on the swing.", "translation": "Biff 爬上了秋千。", "image": "picturebooks/stream-swing/page-05", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "", "announcement": "故事列车到达第 5 站。看看窗外发生了什么。"}, {"title": "故事第 6 页", "content": "Floppy barked and barked.", "translation": "Floppy 叫了又叫。", "image": "picturebooks/stream-swing/page-06", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "听声音站：学一学 Floppy 的叫声。你猜它想告诉大家什么？", "announcement": "故事列车到达第 6 站。注意观察 Floppy。"}, {"title": "故事第 7 页", "content": "Chip climbed on the swing. Floppy barked and barked and barked.", "translation": "Chip 爬上了秋千。Floppy 不停地叫。", "image": "picturebooks/stream-swing/page-07", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "", "announcement": "故事列车到达第 7 站。看看窗外发生了什么。"}, {"title": "故事第 8 页", "content": "Kipper went on the swing. “What a silly dog!” said Kipper.", "translation": "Kipper 上了秋千。“真是只傻狗！”Kipper 说。", "image": "picturebooks/stream-swing/page-08", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "", "announcement": "故事列车到达第 8 站。看看窗外发生了什么。"}, {"title": "故事第 9 页", "content": "Wilma went on too. “What a silly dog!” said Wilma.", "translation": "Wilma 也上去了。“真是只傻狗！”Wilma 说。", "image": "picturebooks/stream-swing/page-09", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "车厢观察员：秋千上的人越来越多了。你觉得接下来会怎样？", "announcement": "故事列车到达第 9 站。看看窗外发生了什么。"}, {"title": "故事第 10 页", "content": "The children went home. Floppy looked at the rope.", "translation": "孩子们回家了。Floppy 看着绳子。", "image": "picturebooks/stream-swing/page-10", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "小火车先停一停：这次 Floppy 看的是哪里的绳子？先猜结局，再翻页。", "announcement": "故事列车到达第 10 站。注意观察 Floppy。"}, {"title": "故事第 11 页", "content": "Splash! Oh no!", "translation": "扑通！哦，不！", "image": "picturebooks/stream-swing/page-11", "audioLanguage": "en", "voiceProfile": "story-narrator", "prompt": "终点讨论：桥发生了什么？你现在觉得 Floppy 是一只怎样的狗？", "announcement": "故事列车到达第 11 站。看看窗外发生了什么。"}]}', 1, 3 FROM unit JOIN theme ON theme.id = unit.theme_id WHERE theme.name = '绘本小火车' AND unit.name = '溪边秋千 · 绘本1';
INSERT INTO lesson (unit_id, name, type, content, sort_order, star_reward) SELECT unit.id, '问答站 · 站长挑战', 'QUIZ', '{"type": "QUIZ", "picturebook": true, "bookTitle": "溪边秋千 · 绘本1", "items": [{"question": "第一节车厢装哪幅图？听一听，找出小溪边的场景。", "audioText": "The children went to the stream.", "image": "picturebooks/train-station", "options": [{"text": "孩子们来到小溪边", "image": "picturebooks/stream-swing/page-01", "showText": false}, {"text": "孩子们落水了", "image": "picturebooks/stream-swing/page-11", "showText": false}], "answer": 0, "hint": "stream 是小溪。找找孩子们走在小桥上的那一页。", "audioLanguage": "en", "voiceProfile": "challenge-curious"}, {"question": "秋千站到了：他们在玩什么？", "audioText": "What are the children playing on?", "image": "picturebooks/stream-swing/page-02", "options": ["A train.", "A swing."], "answer": 1, "hint": "swing 是秋千。再看看树下吊着什么。", "audioLanguage": "en", "voiceProfile": "challenge-curious"}, {"question": "声音车厢：谁在不停地叫？", "audioText": "Who barked and barked?", "image": "picturebooks/stream-swing/page-06", "options": ["Floppy.", "Chip."], "answer": 0, "hint": "barked 是狗叫的声音。这只狗叫 Floppy。", "audioLanguage": "en", "voiceProfile": "challenge-curious"}, {"question": "站长请你找图：哪一页是 Splash？", "audioText": "Splash! Oh no!", "image": "picturebooks/train-station", "options": [{"text": "小狗看着绳子", "image": "picturebooks/stream-swing/page-04", "showText": false}, {"text": "水花溅起来了", "image": "picturebooks/stream-swing/page-11", "showText": false}], "answer": 1, "hint": "Splash 是落水溅起水花的声音。", "audioLanguage": "en", "voiceProfile": "challenge-curious"}, {"question": "到站啦！站长说 Stop，司机应该做什么？", "audioText": "Stop!", "image": "picturebooks/train-station", "options": ["停下 · STOP", "出发 · GO"], "answer": 0, "hint": "Stop 表示停下。列车要停稳，再迎接乘客。", "audioLanguage": "en", "voiceProfile": "challenge-curious"}, {"question": "乘客上车啦！哪一句是在请大家上车？", "audioText": "Which one means: everyone, get on the train?", "image": "picturebooks/train-station", "options": ["Oh no!", "All aboard!"], "answer": 1, "hint": "All aboard! 是请大家上车。跟站长一起说一遍。", "audioLanguage": "en", "voiceProfile": "challenge-curious"}]}', 2, 3 FROM unit JOIN theme ON theme.id = unit.theme_id WHERE theme.name = '绘本小火车' AND unit.name = '溪边秋千 · 绘本1';
INSERT INTO lesson (unit_id, name, type, content, sort_order, star_reward) SELECT unit.id, '小司机站 · 词语装车', 'READING', '{"type": "READING", "picturebook": true, "bookTitle": "溪边秋千 · 绘本1", "items": [{"title": "词语装车 · 小溪", "content": "stream", "translation": "小溪。指一指画面中的水流，再把 stream 说给站长听。", "image": "picturebooks/stream-swing/page-01", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "speak"}, {"title": "词语装车 · 秋千", "content": "swing", "translation": "秋千。指一指轮胎秋千，说完就把这个词装进车厢。", "image": "picturebooks/stream-swing/page-02", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "speak"}, {"title": "词语装车 · 绳子", "content": "rope", "translation": "绳子。找一找 Floppy 看的绳子，试着说 rope。", "image": "picturebooks/stream-swing/page-04", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "speak"}, {"title": "站长广播", "content": "All aboard!", "translation": "大家上车！请你当站长，大声邀请乘客上车。", "image": "picturebooks/train-station", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "speak"}, {"title": "课堂词汇车厢", "content": "children. stream. swing. climb on. rope. bark. push. silly.", "translation": "课堂词汇表：孩子、小溪、秋千、爬上、绳子、吠叫、推、愚蠢的。", "image": "picturebooks/stream-swing/vocabulary", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "speak"}, {"title": "拼读加油站 · am / an", "content": "ram. yam. jam. dam. fan. man. pan. can.", "translation": "跟着课堂练习读单词。原扫描件部分小标题不清晰，以示例单词为准。", "image": "picturebooks/stream-swing/phonics-am-an", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "speak"}, {"title": "拼读加油站 · ad", "content": "dad. pad.", "translation": "读一读 dad 和 pad。今天的词语列车装好了！", "image": "picturebooks/stream-swing/phonics-ad", "audioLanguage": "en", "voiceProfile": "story-narrator", "trainAction": "speak"}]}', 3, 3 FROM unit JOIN theme ON theme.id = unit.theme_id WHERE theme.name = '绘本小火车' AND unit.name = '溪边秋千 · 绘本1';
